        welcome_back = {
            { t = "You are back! Bean saw you first this time, from the very top of Maize. Bean is unbearable about this.", when = { away = 3 } },
            { t = "Welcome home. We kept growing, all three, and saved the best shade for you.", when = { away = 3 } },
            { t = "There you are. We counted the days you were gone. Three counts, one number. We missed you the same.", when = { away = 3 } },
            { t = "Hello again! Nothing much happened. Maize grew. Bean talked. Squash spread. The usual.", when = { away = 3 } },
            { t = "You came back to the mound. Things come back to a mound: seeds, rain, the people who tend us.", when = { away = 3 } },
            { t = "We leaned toward the gate the whole time. We are not built for leaning that far. We managed.", when = { away = 3 } },
            { t = "No need to explain. Seasons come and go. You came back, and that is what matters to a field.", when = { away = 3 } },
            { t = "Welcome back. Squash says sit. Maize says rest. Bean says tell us everything. Do all three.", when = { away = 3 } },
            { t = "Here you are! The mound felt one short. Now the mound feels just right.", when = { away = 3 } },
            { t = "You have been away, and we have been here, keeping each other company and saving you a place.", when = { away = 3 } },
            { t = "Back in the cold season! We are seeds in the jar, but we heard you come in. Three small rattles of welcome.", when = { away = 3, season = "winter" } },
        },
        finished = {
            "You finished {last}! A whole harvest. Three cheers from the mound.",
            "{last} is done. Maize bows. Bean claps leaves. Squash says now rest, please.",
            "The end of {last}. Keep a few seeds of the book, the best lines. Plant them later.",
