        level = {
            { t = "We talked about you last night, all three. Bean talked most. We agreed you belong near the mound.", when = { level = 2, max_level = 2 } },
            { t = "Maize noticed you sit on the side where Squash's shade is best. Squash noticed first, and kept quiet.", when = { level = 2, max_level = 2 } },
            { t = "You can tell which of us is which now. That makes you nearly family. We do not say nearly lightly.", when = { level = 2, max_level = 2 } },
            { t = "Something we do not say to everyone: we are stronger together, and stronger still with you here.", when = { level = 3, max_level = 3 } },
            { t = "Bean has wound one small turn toward your chair. Maize allowed the turn. Maize does not allow much.", when = { level = 3, max_level = 3 } },
            { t = "Squash wants you to know Squash would shade you if you lay down in the field. Squash is not sentimental. This is a fact.", when = { level = 3, max_level = 3 } },
            { t = "Maize: We were planted by hands that knew the old way. Bean: And now your hands! Squash: Careful hands. Good.", when = { level = 4, max_level = 4 } },
            { t = "A secret from all of us: three is a good number. Lately we have wondered what four would feel like.", when = { level = 4, max_level = 4 } },
            { t = "Every year we leave seeds for the next. Every year we hope someone will keep them. We think you would.", when = { level = 4, max_level = 4 } },
            { t = "We have a name for you now: the fourth of us. Bean chose the name. Maize and Squash agreed at once.", when = { level = 5, max_level = 5 } },
            { t = "One mound, four of us. You hold the book, we hold the ground. In the old planting, everyone holds something.", when = { level = 5, max_level = 5 } },
            { t = "Seasons pass, we rest in the jar, we come back to the mound. We will always come back, as long as you are here to read.", when = { level = 5, max_level = 5 } },
        },
        streak = {
            "{streak} days in a row! Maize counted, Bean counted, Squash counted. We all got {streak}. Agreement!",
            "{streak} days of reading. Like watering a mound: little and often, and look what grows.",
            "{streak} days running. Bean says amazing. Maize says steady. Squash says both.",
            "Day {streak}. Every day a seed. A whole row of them now.",
            "A streak of {streak}. You read the way we grow: together, every day, without fuss.",
            "{streak} days, and none missed. A field remembers that kind of care.",
            "{streak} days. If a day slips by some time, the mound will still be here, and so will we. For now, three cheers.",
            "{streak} days of pages. A good rhythm. We know rhythms: plant, grow, gather, rest.",
        },
        anniversary = {
            "{days} days since you chose us. Three for the price of one. Very wise.",
            "{days} days together! Maize has grown taller, Bean chattier, Squash fonder. Of you, mostly.",
            "{days} days. We have counted them the way we count everything: together, and out loud.",
            "We have known you {days} days. Seeds remember. We will remember every one.",
            "{days} days of you near the mound. We feel more like four than three now.",
            "{days} days ago you picked a family. Families come with noise. You have taken the noise very well.",
            "{days} days! Bean wants a party. Maize wants a quiet moment. Squash says one of each. Squash wins.",
            "{days} days. Many hands have tended mounds like ours over many centuries. Yours are among the kindest.",
        },
        quote = {
            { t = "\u{201C}{quote}\u{201D} All three of us liked that one. That almost never happens.", when = { quote = true } },
            { t = "You marked this: \u{201C}{quote}\u{201D} Maize nodded. Bean gasped. Squash agreed.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} That one will keep all winter, like good seed.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} Bean wants that read again. Maize does too, quietly.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} Squash calls that good, solid sense. High praise, from Squash.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} Words that hold each other up. Like us.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} Maize has been standing very still since you marked that.", when = { quote = true } },
            { t = "Remember this one? \u{201C}{quote}\u{201D} We do. All three of us.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} Bean is repeating that to everyone in the field.", when = { quote = true } },
            { t = "\u{201C}{quote}\u{201D} That belongs in the jar with the best seeds.", when = { quote = true } },
        },
    },
    beats = {
        { id = "jar", at = 15, title = "The jar",
            text = "We began as seeds in one clay jar: yellow kernels, speckled beans, flat pale squash seeds, mixed up together for the winter. Bean talked in the dark the whole time. Maize kept count of the days. Squash slept, and says sleeping was the most useful thing anyone did." },
        { id = "maize_first", at = 40, title = "Maize first",
            text = "In spring a hand made a mound of earth and put Maize in first, alone. Maize came up out of the soil and waited, a hand high, for the others. Maize says the waiting was not hard. Bean says Maize was lonely. Maize has never answered that." },
        { id = "holding_up", at = 80, title = "Holding up",
            text = "Then Bean and Squash went in around Maize. Bean came up talking and reached for the nearest tall thing, which was Maize, and wound round and round. Maize held still. That was the first time one of us held another up. We have been at that ever since." },
        { id = "ground", at = 140, title = "The green roof",
            text = "Squash came up slowly, then all at once, big leaves rolling over the soil like a green roof. Under them the ground stayed cool and damp, and the weeds gave up. Nobody thanked Squash that summer. Squash says that is fine. Squash remembers, though." },
        { id = "under", at = 220, title = "Under the soil",
            text = "Here is a secret under the soil. Bean's roots carry little round lumps, and in them live tiny helpers who pull food for the earth out of the air. Maize grew greener and did not know why. Bean knew. Bean told everybody, all season." },
        { id = "hands", at = 320, title = "The hands",
            text = "The hands that planted us knew the old way, taught by someone who learned from someone before. We do not know how far back the teaching goes. Many peoples across the Americas kept this planting for many hundreds of years. We are one small mound in a very long line." },
        { id = "harvest", at = 450, title = "Harvest",
            text = "In autumn the hands came back for Maize's ears, Bean's dry pods, and Squash, round and heavy. They took what they needed and saved the best seeds for next year. We felt a little emptier and very proud. That is how harvest feels, from inside." },
        { id = "lid", at = 600, title = "Three marks",
            text = "Our jar had a mark scratched into the lid: three small lines. We never learned who scratched the lines, or whether there were once others. Bean has a hundred theories. Maize thinks the lines are simply us. Squash says the lid keeps the mice out, and that is enough." },
        { id = "shelf", at = 800, title = "The high shelf",
            text = "One winter the jar went up onto a high shelf and stayed there. Spring came and went, and nobody lifted us down. We slept a long time. Bean stopped talking, which worried Maize more than anything. Seeds keep, though. Seeds are good at keeping." },
        { id = "your_hands", at = 1050, title = "New hands",
            text = "Then new hands took down the jar, shook us into a palm, and turned the lid over to look at the three marks. Your hands. You made a mound, put Maize in first, and waited. Nobody had to tell you. We knew then we had come to the right garden." },
        { id = "fourth", at = 1400, title = "A fourth",
            text = "We have grown beside you through {total} pages now. Maize stands, Bean climbs, Squash shades, and you read. Some gardeners plant a fourth at the edge of the mound, a flower for the bees. We think ours reads." },
        { id = "four_marks", at = 1800, title = "Four marks",
            text = "Last night Bean finally said the theory out loud: three lines on a lid were only ever a beginning. Maize agreed. Squash found a sharp stone. There are four lines on the lid now. Every year we rest and every year we come back, and now we come back to you." },
    },
}
